import pytest
from unittest.mock import MagicMock

from ansible.parsing.dataloader import DataLoader
from ansible.template import Templar
from ansible.plugins.action.validate_argument_spec import ActionModule


def _make_action(variables=None):
    """Build an ActionModule with a real Templar so {{ }} actually resolves."""
    loader = DataLoader()
    templar = Templar(loader=loader, variables=variables or {})
    return ActionModule(
        task=MagicMock(),
        connection=MagicMock(),
        play_context=MagicMock(),
        loader=loader,
        templar=templar,
        shared_loader_obj=MagicMock(),
    )


def test_picks_only_spec_args_from_task_vars():
    action = _make_action()
    spec = {'name': {'type': 'str'}, 'count': {'type': 'int'}}
    task_vars = {'name': 'web', 'count': 3, 'unrelated': 'x'}

    result = action.get_args_from_task_vars(spec, task_vars)

    assert result == {'name': 'web', 'count': 3}


def test_args_missing_from_task_vars_are_excluded():
    action = _make_action()
    spec = {'name': {'type': 'str'}, 'count': {'type': 'int'}}

    result = action.get_args_from_task_vars(spec, {'name': 'web'})

    assert result == {'name': 'web'}


def test_values_are_templated():
    action = _make_action({'my_name': 'web01'})
    spec = {'name': {'type': 'str'}}
    task_vars = {'name': '{{ my_name }}'}

    result = action.get_args_from_task_vars(spec, task_vars)

    assert result == {'name': 'web01'}


def test_nested_structures_are_templated():
    action = _make_action({'port': 8080})
    spec = {'config': {'type': 'dict'}}
    task_vars = {'config': {'port': '{{ port }}'}}

    result = action.get_args_from_task_vars(spec, task_vars)

    assert result == {'config': {'port': 8080}}


def test_empty_task_vars_returns_empty_dict():
    action = _make_action()
    spec = {'name': {'type': 'str'}}

    assert action.get_args_from_task_vars(spec, {}) == {}
```

What this covers:
1. **Filtering** â only names present in both `argument_spec` and `task_vars` are returned.
2. **Templating** â Jinja expressions (flat and nested dicts) are resolved via a real `Templar`, not a mock, so the test exercises actual templating behavior.
3. **Edge cases** â empty `task_vars`, missing optional args.

Note: `ActionModule` is instantiated directly with mocks for everything except `loader`/`templar`, because `get_args_from_task_vars` only touches `self._templar`.

